SELECT ssto.*, u.username, u.avatar, sst.detail, sst.start_date, sst.end_date, ori.id AS refund_id, ori.ticket_order_id AS refund_ticket_order_id, ori.status AS refund_status, ori.reject_reason AS refund_reject_reason, ori.reject_refund_time AS refund_reject_refund_time, ori.refund_time AS refund_time, ori.create_time AS refund_create_time FROM scenic_spot_ticket_order ssto LEFT JOIN user u ON u.id = ssto.user_id LEFT JOIN scenic_spot_ticket sst ON sst.id = ssto.scenic_spot_ticket_id LEFT JOIN order_refund_info ori ON ori.ticket_order_id = ssto.id
AND ssto.scenic_id = #{scenicSpotTicketId}
AND ssto.status = #{status}
AND ssto.status IN
#{statusItem}
AND ssto.user_id = #{userId}
AND ssto.price BETWEEN #{minPrice} AND #{maxPrice}
AND ssto.create_time BETWEEN #{startTime} AND #{endTime}
AND EXISTS ( SELECT 1 FROM order_refund_info ori1 WHERE ori1.ticket_order_id = ssto.id AND ori1.status = #{refundStatus} AND ori1.create_time = ( SELECT MAX(ori2.create_time) FROM order_refund_info ori2 WHERE ori2.ticket_order_id = ssto.id ) )
ORDER BY ssto.create_time DESC
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM scenic_spot_ticket_order ssto


        AND ssto.scenic_id = #{scenicSpotTicketId}


        AND ssto.status = #{status}


        AND ssto.status IN

            #{statusItem}



        AND ssto.user_id = #{userId}


        AND ssto.price BETWEEN #{minPrice} AND #{maxPrice}


        AND ssto.create_time BETWEEN #{startTime} AND #{endTime}


        AND EXISTS (
        SELECT 1 FROM order_refund_info ori1
        WHERE ori1.ticket_order_id = ssto.id
        AND ori1.status = #{refundStatus}
        AND ori1.create_time = (
        SELECT MAX(ori2.create_time) FROM order_refund_info ori2
        WHERE ori2.ticket_order_id = ssto.id
        )
        )
